import{matriarchCenter,clearBossFootprint}from'./matriarch-arena.js';
import{isFloor}from'./cave-layout.js';import{bossDamage}from'./bosses.js';import{creatureFor}from'./creatures.js';
export const VINE_RULES=Object.freeze({version:4,warning:2,escapeGain:6,grace:5,crush:6,maxCrushes:3,feedHits:2,growBeats:4,chargeBeats:12,hatchCount:3,openBeats:8,batHP:2,batCap:3,summonGap:12});
export const rootActive=b=>b?.boss===true&&b.bossIndex===1&&b.vine?.version===4;
export const rootTarget=n=>n?.sapRoot===true;
export const rootBat=n=>Number.isSafeInteger(n?.vineOwner);
export const rootBoss=room=>room.enemies.find(b=>rootActive(b)&&b.hp>0);
export const rootTargets=room=>{const f=rootBoss(room)?.vine.feed;return f?.hp>0?[f]:[];};
export const rootBodyBlocks=(room,x,y)=>room.enemies.some(b=>rootActive(b)&&b.hp>0&&Math.abs(b.x-x)<=1&&Math.abs(b.y-y)<=1);
export function rootBodyCells(room){return room.enemies.filter(b=>rootActive(b)&&b.hp>0).flatMap(b=>[-1,0,1].flatMap(y=>[-1,0,1].map(x=>({x:b.x+x,y:b.y+y}))));}
export function rootApproach(b,p){const dx=p.x-b.x,dy=p.y-b.y;return Math.abs(dx)>=Math.abs(dy)?{x:b.x+(dx<0?-2:2),y:b.y}:{x:b.x,y:b.y+(dy<0?-2:2)};}
export function rootEscape(room,p,walkable){if(!rootBodyBlocks(room,p.x,p.y))return null;const b=rootBoss(room);return[-2,-1,0,1,2].flatMap(y=>[-2,-1,0,1,2].map(x=>({x:b.x+x,y:b.y+y}))).filter(q=>walkable(room,q.x,q.y)).sort((a,z)=>(Math.abs(a.x-p.x)+Math.abs(a.y-p.y))-(Math.abs(z.x-p.x)+Math.abs(z.y-p.y)))[0]||null;}
const radius=(b,p)=>Math.hypot(p.x-b.x,p.y-b.y);
export function vineEscapePath(room,b,p,walkable){const start=b.vine.grab?.stage==='bound'?b.vine.grab.origin:radius(b,p),queue=[{p,path:[]}],seen=new Set([p.x+','+p.y]);for(const e of queue){if(radius(b,e.p)-start>=VINE_RULES.escapeGain-1e-8)return e.path;if(e.path.length===16)continue;for(const[dx,dy]of[[0,1],[-1,0],[1,0],[0,-1]]){const q={x:e.p.x+dx,y:e.p.y+dy},key=q.x+','+q.y;if(seen.has(key)||!walkable(room,q.x,q.y)||radius(b,q)<=radius(b,e.p)+1e-8)continue;seen.add(key);queue.push({p:q,path:[...e.path,q]});}}return null;}
function event(s,b,type,beat,data={}){s.run?.events.push({type,id:`vine:${s.run.room.seed}:${b.id}:${type}:${beat}:${b.vine.serial}`,sourceId:b.id,bossIndex:1,beat,x:b.x,y:b.y,...data});}
export function enableMatriarch(b,room=null){if(!b?.boss||b.bossIndex!==1)throw Error('Matriarch only');delete b.root;const at=room?matriarchCenter(room):{x:10,y:7};b.x=at.x;b.y=at.y;b.windup=null;b.exposedUntil=-1;b.vine={version:4,serial:0,lastBegin:3,lastResolved:3,nextFeed:4,feed:null,openFrom:-1,openUntil:-1,nextGrab:6,grab:null,nextSummon:-1,bushes:[],pair:0,hitAt:-1,impactAt:-1,breakAt:-1,breakPoint:null,hatchAt:-1,hatchPoint:null,phase:1};if(room){b.vine.centered=true;clearBossFootprint(room,b);}return b;}
export function rootOpen(b,beat){return rootActive(b)&&beat>=b.vine.openFrom&&b.vine.openFrom>=0&&beat<b.vine.openUntil;}
export function rootDamage(b,amount,beat){const old=b.exposedUntil,open=rootOpen(b,beat);b.exposedUntil=open?beat:-1;const damage=bossDamage(b,open?Math.max(6,amount):amount,beat);b.exposedUntil=old;if(damage>0)b.vine.hitAt=beat;return damage;}
export function rootCleanup(room,b){b.vine.grab=null;b.vine.feed=null;b.vine.bushes=[];for(const n of room.enemies)if(n.vineOwner===b.id)n.hp=0;}
export function rootBatKilled(room,n,beat){const b=room.enemies.find(b=>rootActive(b)&&b.id===n.vineOwner&&b.hp>0);if(b&&!room.enemies.some(e=>e.vineOwner===b.id&&e.hp>0))b.vine.nextSummon=Math.max(b.vine.nextSummon,beat+12);}
export function rootPrimary(s,f,beat,visual){const b=rootBoss(s.run.room);if(!b||!rootTarget(f))return false;visual.outcome='blocked';visual.damage=0;if(!['active','ripe'].includes(f.state)||f.hp<=0||f.lastHit===beat)return true;f.lastHit=beat;f.hp--;visual.outcome='damage';visual.damage=1;event(s,b,'sapCut',beat,{at:{x:f.x,y:f.y},remaining:f.hp});if(f.hp===0){f.state='cut';b.vine.openFrom=beat+1;b.vine.openUntil=beat+1+VINE_RULES.openBeats;b.vine.nextFeed=beat+8;b.vine.impactAt=beat;b.exposedUntil=beat+VINE_RULES.openBeats;event(s,b,'sapSevered',beat,{at:{x:f.x,y:f.y},from:beat+1,until:beat+1+VINE_RULES.openBeats});}return true;}
export const SAP_DIRECTIONS=Object.freeze([{id:'NE',dx:1,dy:-1},{id:'SE',dx:1,dy:1},{id:'E',dx:1,dy:0},{id:'W',dx:-1,dy:0},{id:'SW',dx:-1,dy:1},{id:'NW',dx:-1,dy:-1}]);
export function sapWallSites(room,b,walkable){const points=[];for(const dir of SAP_DIRECTIONS){const ray=[];for(let k=2;k<Math.max(room.cols,room.rows);k++){const p={x:b.x+dir.dx*k,y:b.y+dir.dy*k};if(!isFloor(room,p.x,p.y))break;ray.push(p);}for(let i=Math.max(0,ray.length-2);i>=Math.max(0,ray.length-4);i--){const p=ray[i];if(!p||radius(b,p)<4||!walkable(room,p.x,p.y)||room.nodes.some(n=>n.hp>0&&radius(n,p)<1.7)||room.enemies.some(n=>n.hp>0&&radius(n,p)<2))continue;points.push({...p,direction:dir.id});break;}}return points;}
function rootRandom(seed){let x=seed>>>0;x^=x<<13;x^=x>>>17;x^=x<<5;return(x>>>0)/4294967296;}
function plant(s,b,beat,cb){const m=b.vine;if(s.run.room.enemies.some(n=>n.vineOwner===b.id&&n.hp>0)){m.nextFeed=beat+2;return;}const player=s.run.player,dx=player.x-b.x,dy=player.y-b.y,len=Math.hypot(dx,dy)||1,slots=sapWallSites(s.run.room,b,cb.walkable).map((p,i)=>{const d=radius(b,p),opposite=((p.x-b.x)*dx+(p.y-b.y)*dy)/(d*len);return{...p,opposite,score:opposite+rootRandom(s.run.room.seed^Math.imul(m.serial+1,2654435761)^Math.imul(i+1,2246822519))*.45};}),away=slots.filter(p=>p.opposite<-.15),pool=away.length?away:slots;pool.sort((a,b)=>a.score-b.score);const p=pool[0];if(!p){m.nextFeed=beat+2;return;}m.feed={id:-(b.id*100000+(++m.serial)),sapRoot:true,type:'enemy',kind:2,x:p.x,y:p.y,direction:p.direction,hp:2,maxHp:2,state:'forming',born:beat,activeAt:beat+VINE_RULES.growBeats,charge:0,chargeAt:beat+VINE_RULES.growBeats-1,lastHit:-1,start:{x:b.x,y:b.y}};event(s,b,'sapGrow',beat,{at:{x:p.x,y:p.y},direction:p.direction});}
function bushClear(s,b,p,cb){const room=s.run.room;return cb.walkable(room,p.x,p.y)&&radius(s.run.player,p)>=2&&!room.nodes.some(n=>n.hp>0&&radius(n,p)<2)&&!room.enemies.some(n=>n.hp>0&&radius(n,p)<2)&&(!b.vine.feed||radius(b.vine.feed,p)>=2);}
function spawnPositions(s,b,cb){const out=[];for(const[dx,dy]of[[-5,-2],[5,-2],[-5,2],[5,2],[-3,-3],[3,-3],[-4,3],[4,3]]){const p={x:b.x+dx,y:b.y+dy};if(!bushClear(s,b,p,cb)||radius(s.run.player,p)<3)continue;out.push(p);if(out.length===2)break;}return out;}
function begin(s,b,beat,cb){const m=b.vine;if(beat<4||beat<=m.lastBegin)return;m.lastBegin=beat;m.phase=Math.max(m.phase,b.hp<=b.maxHp/2?2:1);
 if(beat>=m.nextFeed&&(!m.feed||m.feed.hp<=0))plant(s,b,beat,cb);
 if(m.feed?.state==='forming'&&beat>=m.feed.activeAt){m.feed.state='active';event(s,b,'sapReady',beat,{at:{x:m.feed.x,y:m.feed.y}});}
 if(!m.grab&&beat>=m.nextGrab){const target={...s.run.player};if(vineEscapePath(s.run.room,b,target,cb.walkable)){m.serial++;m.grab={stage:'warn',target,started:beat,due:beat+2,serial:m.serial,origin:0,caughtAt:-1,nextCrush:-1,crushes:0,progress:0};event(s,b,'vineWarning',beat,{target});}else{m.nextGrab=beat+3;event(s,b,'vineSkipped',beat,{target});}}
 if(m.phase===2&&m.nextSummon<0)m.nextSummon=beat+2;
 const alive=s.run.room.enemies.filter(n=>n.vineOwner===b.id&&n.hp>0);
 if(m.phase===2&&beat>=m.nextSummon&&!alive.length&&!m.feed?.hp&&!m.bushes.length&&m.grab?.stage!=='bound'){const points=spawnPositions(s,b,cb);if(points.length===2){m.pair++;m.bushes=points.map((p,i)=>({...p,born:beat,due:beat+2,pair:m.pair,slot:i}));event(s,b,'bushWarning',beat,{points});}else m.nextSummon=beat+2;}
}
export function eggSpawnSites(r,b,f,walkable){const out=[];for(const[dx,dy]of[[-1,0],[0,1],[0,-1],[1,0],[-1,1],[-1,-1],[1,1],[1,-1]]){const p={x:f.x+dx,y:f.y+dy};if(!walkable(r.room,p.x,p.y)||p.x===r.player.x&&p.y===r.player.y||r.room.nodes.some(n=>n.hp>0&&radius(n,p)<1)||r.room.enemies.some(n=>n.hp>0&&radius(n,p)<1))continue;out.push(p);if(out.length===3)break;}return out;}
function resolve(s,b,beat,cb){const r=s.run,m=b.vine;if(beat<4||beat<=m.lastResolved)return;m.lastResolved=beat;
 const f=m.feed;if(f?.state==='active'&&f.hp>0&&beat>f.chargeAt){f.charge=Math.min(VINE_RULES.chargeBeats,f.charge+1);f.chargeAt=beat;event(s,b,'sapPulse',beat,{at:{x:f.x,y:f.y},charge:f.charge});if(f.charge===VINE_RULES.chargeBeats){f.state='ripe';event(s,b,'eggReady',beat,{at:{x:f.x,y:f.y}});}}
 if(f?.state==='ripe'&&f.hp>0&&!r.room.enemies.some(n=>n.vineOwner===b.id&&n.hp>0)){const points=eggSpawnSites(r,b,f,cb.walkable);if(points.length===3){m.pair++;for(const p of points)r.room.enemies.push({id:r.room.nextId++,type:'enemy',kind:1,species:creatureFor(r.floor,1).id,...p,hp:2,maxHp:2,vineOwner:b.id,vinePair:m.pair,born:beat,eggBorn:true,windup:null,stunUntil:beat+1,recoverUntil:beat+2});f.hp=0;f.state='hatched';f.hatchAt=beat;m.hatchAt=beat;m.hatchPoint={x:f.x,y:f.y};m.nextFeed=beat+6;m.nextSummon=beat+12;event(s,b,'eggHatch',beat,{at:{x:f.x,y:f.y},count:3});}}

 const g=m.grab;if(g?.stage==='warn'&&beat>=g.due){if(r.player.x===g.target.x&&r.player.y===g.target.y&&vineEscapePath(r.room,b,r.player,cb.walkable)){g.stage='bound';g.caughtAt=beat;g.origin=radius(b,r.player);g.nextCrush=beat+VINE_RULES.grace;event(s,b,'vineCaught',beat,{target:{...r.player}});}else{m.grab=null;m.nextGrab=beat+6;event(s,b,'vineMiss',beat);}}
 else if(g?.stage==='bound'){g.progress=Math.max(0,radius(b,r.player)-g.origin);if(g.progress>=VINE_RULES.escapeGain-1e-8){m.breakAt=beat;m.breakPoint={...r.player};m.grab=null;m.nextGrab=beat+8;event(s,b,'vineBreak',beat,{at:{...r.player}});}else if(beat>=g.nextCrush){g.crushes++;g.nextCrush=beat+1;event(s,b,'vineCrush',beat,{at:{...r.player},count:g.crushes});cb.contact(b,6,beat);if(!s.run||r.recovery?.active)return;if(g.crushes>=3){m.grab=null;m.nextGrab=beat+8;event(s,b,'vineRelease',beat);}}}
 if(m.bushes.length&&beat>=m.bushes[0].due){if(m.grab?.stage==='bound'){for(const p of m.bushes)p.due=beat+1;}else{const alive=r.room.enemies.filter(n=>n.vineOwner===b.id&&n.hp>0),safe=m.bushes.length===2&&m.bushes.every(p=>bushClear(s,b,p,cb));if(!alive.length&&safe){for(const p of m.bushes)r.room.enemies.push({id:r.room.nextId++,type:'enemy',kind:1,species:creatureFor(r.floor,1).id,x:p.x,y:p.y,hp:2,maxHp:2,vineOwner:b.id,vinePair:m.pair,born:beat,windup:null,stunUntil:beat,recoverUntil:beat+1});event(s,b,'batsEmerged',beat,{pair:m.pair,count:2});}else event(s,b,'bushCancelled',beat);m.bushes=[];m.nextSummon=beat+(safe?10:4);}}
}
export function rootAdvance(s,beat,cb){const r=s.run;if(!r||r.room.cleared||r.recovery?.active)return;for(const b of r.room.enemies){if(!rootActive(b)||b.hp<=0)continue;for(let at=b.vine.lastResolved+1;at<beat;at++){begin(s,b,at,cb);resolve(s,b,at,cb);if(!s.run||r.recovery?.active||b.hp<=0)return;}begin(s,b,beat,cb);}}
export function rootResolve(s,beat,cb){if(!s.run||s.run.room.cleared||s.run.recovery?.active)return;for(const b of s.run.room.enemies)if(rootActive(b)&&b.hp>0)resolve(s,b,beat,cb);}
export function rootCaption(b,beat){const m=b.vine,f=m.feed;return m.hatchAt>=0&&beat-m.hatchAt<.8?'OVO ECLODIU · 3 MORCEGOS':m.grab?.stage==='bound'?'ESTIQUE A RAIZ · '+Math.floor(m.grab.progress)+'/6':m.grab?.stage==='warn'?'RAIZ SE APROXIMANDO':rootOpen(b,beat)?'CASCA ABERTA · ATAQUE!':f?.state==='forming'?'RAIZ CRESCENDO ATÉ A PAREDE':f?.state==='ripe'?'OVO PRONTO · CORTE OU ENFRENTE':f?.hp>0?'OVO DE SEIVA · '+f.charge+'/'+VINE_RULES.chargeBeats:'APROXIME-SE E ATAQUE';}
export function validMatriarch(b,room){const int=Number.isSafeInteger,point=p=>p&&int(p.x)&&int(p.y)&&isFloor(room,p.x,p.y);if(b.vineOwner!==undefined){const owner=room.enemies.find(o=>o.id===b.vineOwner&&rootActive(o));return !!owner&&int(b.vineOwner)&&b.kind===1&&b.maxHp===2&&b.hp>=0&&b.hp<=2&&int(b.vinePair)&&(b.hp===0?b.vinePair>0&&b.vinePair<=owner.vine.pair:b.vinePair===owner.vine.pair)&&int(b.born)&&point(b)&&(b.hp===0||owner.hp>0);}if(b.vine===undefined)return !(b.bossIndex===1&&b.root?.version===1);if(!rootActive(b))return false;const m=b.vine;const center=m.centered?matriarchCenter(room):{x:10,y:7};if(m.centered!==undefined&&m.centered!==true||b.x!==center.x||b.y!==center.y||!['serial','lastBegin','lastResolved','nextFeed','openFrom','openUntil','nextGrab','nextSummon','pair','hitAt','impactAt','breakAt','hatchAt','phase'].every(k=>int(m[k]))||m.breakPoint&&!point(m.breakPoint)||m.hatchPoint&&!point(m.hatchPoint)||m.serial<0||m.serial>1e6||![1,2].includes(m.phase)||!Array.isArray(m.bushes)||![0,2].includes(m.bushes.length))return false;
 const f=m.feed;if(f&&!SAP_DIRECTIONS.some(d=>d.id===f.direction))return false;if(f?.hatchAt!==undefined&&(!int(f.hatchAt)||f.hatchAt<f.activeAt))return false;if(f&&(f.state==='hatched'&&(f.hp!==0||f.charge!==VINE_RULES.chargeBeats||f.hatchAt===undefined)||f.state==='ripe'&&(f.hp<1||f.charge!==VINE_RULES.chargeBeats)))return false;if(f&&(!rootTarget(f)||!point(f)||!int(f.id)||f.id>=0||![0,1,2].includes(f.hp)||f.maxHp!==2||!['forming','active','ripe','cut','hatched'].includes(f.state)||!['born','activeAt','charge','chargeAt','lastHit'].every(k=>int(f[k]))||f.activeAt!==f.born+VINE_RULES.growBeats||f.charge<0||f.charge>VINE_RULES.chargeBeats||!point(f.start)))return false;
 const g=m.grab;if(g&&(!['warn','bound'].includes(g.stage)||!point(g.target)||!['started','due','serial','caughtAt','nextCrush','crushes'].every(k=>int(g[k]))||!Number.isFinite(g.origin)||!Number.isFinite(g.progress)||g.origin<0||g.progress<0||g.crushes<0||g.crushes>3||g.due!==g.started+2))return false;
 if(m.bushes.some(p=>!point(p)||!['born','due','pair','slot'].every(k=>int(p[k]))||p.due<p.born+2))return false;const bats=room.enemies.filter(n=>n.vineOwner===b.id&&n.hp>0);return bats.length<=VINE_RULES.batCap&&bats.every(n=>n.kind===1&&n.maxHp===2&&n.hp<=2&&n.hp>0&&int(n.vinePair)&&point(n));}
